using System;using System.IO;using System.Reflection;using System.Runtime.CompilerServices;using System.Collections.Generic;using Groundworks.FuelFire;using UnityEngine;
class FuelV1Tests {
 static void Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{foreach(var d in new[]{args[0],Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location)}){var p=Path.Combine(d,new AssemblyName(e.Name).Name+".dll");if(File.Exists(p))return Assembly.LoadFrom(p);}return null;};Run();}
 static void Check(bool ok,string text){if(!ok)throw new Exception("FAIL "+text);Console.WriteLine("PASS "+text);}
 static FuelReservoir Tank(){var r=new FuelReservoir();r.slots.Add(new FluidSlot{name="fuel",profile=new FuelProfile{name="fuel",kind=FluidKind.Fuel},amount=100,capacity=100,density=.005});return r;}
 static double Ledger(FuelReservoir r){return r.LiquidRemainingKg+r.CloudKg+r.BurnedFuelKg+r.BurnedOxKg+r.DispersedKg;}
 [MethodImpl(MethodImplOptions.NoInlining)]static void Run(){
  var r=Tank();r.Step(.1,.5,true,false,false);double fuel=r.LiquidRemainingKg,cloud=r.CloudKg;r.Step(.1,0,true,false,false);Check(r.LastLeakKgS==0&&r.LiquidRemainingKg==fuel&&r.CloudKg<cloud,"sealed leak stops new fuel loss while residual vapour disperses");Check(Math.Abs(Ledger(r)-500)<1e-7,"sealed residual vapour preserves the mass ledger");
  r.Burning=true;r.Step(.1,0,true,false,false);Check(r.LastBurnKgS>0&&r.Burning,"already released vapour can finish burning after a patch");double before=r.BurnedFuelKg;r.Step(.1,.5,true,true,false,false);Check(!r.Burning&&r.BurnedFuelKg==before&&r.LastLeakKgS>0,"fire-off mode stops burning and heating without disabling leaks");Check(Math.Abs(Ledger(r)-500)<1e-7,"fire toggle does not create or delete fuel");
  var one=Tank();var two=Tank();one.Step(.1,.5,true,false,false,true,1);two.Step(.1,.5,true,false,false,true,2);Check(Math.Abs(two.LastLeakKgS-one.LastLeakKgS*2)<1e-8,"leak difficulty scales released mass independently of visual quality");
  r=new FuelReservoir();r.slots.Add(new FluidSlot{name="fuel",profile=new FuelProfile{name="fuel",kind=FluidKind.Fuel,oxidizerRatio=2},cloud=4});r.slots.Add(new FluidSlot{name="ox",profile=new FuelProfile{name="ox",kind=FluidKind.Oxidizer},cloud=10});r.Burning=true;r.Step(.1,0,false,false,false);Check(r.BurnedFuelKg>0&&Math.Abs(r.BurnedOxKg/r.BurnedFuelKg-2)<1e-8,"configured fuel/oxidizer mass ratio limits vacuum burning");Check(Math.Abs(Ledger(r)-14)<1e-7,"mixed residual reaction preserves total mass");
  one=Tank();double original=one.LiquidRemainingKg;foreach(double bad in new[]{double.NaN,double.PositiveInfinity,-1.0,0})one.Step(bad,.5,true,true,false);Check(one.LiquidRemainingKg==original&&one.LastLeakKgS==0,"invalid timesteps cannot drain or manufacture fuel");one.Step(.1,double.NaN,true,true,false);Check(one.LiquidRemainingKg==original,"invalid severity cannot corrupt a reservoir");Check(FuelReservoir.VisualScale(double.NaN)==0,"nonfinite flow cannot create invalid particle sizes");
  Check(FuelRules.ImpactSeverity(10,10,.001,12)==0,"tiny debris does not act like a terrain strike on a massive tank");Check(FuelRules.ImpactSeverity(10,1,1,12)>0&&FuelRules.ImpactSeverity(10,1,double.PositiveInfinity,12)>FuelRules.ImpactSeverity(10,1,1,12),"effective collision mass distinguishes mobile bodies from terrain");Check(FuelRules.ImpactSeverity(.5,1,1,12)==0&&FuelRules.ImpactSeverity(double.NaN,1,1,12)==0,"gentle and invalid contacts do not puncture tanks");
  Check(FuelRules.CanRepair(.2f,false,300,true,true,true),"eligible minor cool leak can be patched");Check(!FuelRules.CanRepair(.2f,true,300,true,true,true)&&!FuelRules.CanRepair(.2f,false,400,true,true,true)&&!FuelRules.CanRepair(.5f,false,300,true,true,true),"burning, hot and severe damage cannot be patched");Check(!FuelRules.CanRepair(.2f,false,300,false,true,true)&&!FuelRules.CanRepair(.2f,false,300,true,false,true)&&!FuelRules.CanRepair(.2f,false,300,true,true,false),"repair requires an engineer, proximity and a finite repair kit");
  var profiles=new Dictionary<string,FuelProfile>();profiles["test"]=new FuelProfile{name="test",kind=FluidKind.Fuel,smoke=.3f};var n=new ConfigNode();n.AddValue("name","test");n.AddValue("oxidizerRatio","3");n.AddValue("ignitionTemperature","650");n.AddValue("flameColor","0.1,0.3,0.9,1");FuelRules.ConfigureProfile(n,profiles);Check(profiles["test"].kind==FluidKind.Fuel&&profiles["test"].smoke==.3f&&profiles["test"].oxidizerRatio==3&&profiles["test"].ignitionTemperature==650&&Math.Abs(profiles["test"].flame.b-.9)<.001,"partial custom profile changes preserve unspecified defaults");
  n=new ConfigNode();n.AddValue("name","test");n.AddValue("oxidizerRatio","NaN");n.AddValue("kind","nonsense");n.AddValue("flameColor","NaN,0,0");FuelRules.ConfigureProfile(n,profiles);Check(profiles["test"].oxidizerRatio==3&&profiles["test"].kind==FluidKind.Fuel&&Math.Abs(profiles["test"].flame.b-.9)<.001,"malformed profile values do not poison working fuel settings");
  r=Tank();r.slots[0].cloud=8;var saved=new ConfigNode();saved.AddValue("burning",false);r.Load(saved);Check(r.CloudKg==0,"loading a cloud-free state clears stale vapour rather than duplicating it");
  r=Tank();r.slots[0].amount=0;r.slots[0].cloud=1e-8;r.Burning=true;r.Step(.1,0,true,false,false);Check(r.CloudKg==0&&!r.Burning&&Math.Abs(Ledger(r)-1e-8)<1e-12,"last traces extinguish instead of leaving a frozen permanent vapour fire");
  Console.WriteLine("FUEL V1 REGRESSION CHECKS COMPLETE");
 }
}
